        for c in range(w):
            if grid[r][c] != 0:
                values[(c + r) % period] = grid[r][c]

    # Fill any residues not directly specified by extending the known cyclic
    # sequence through the observed colored cells.
    for k in range(period):
        if k not in values:
            known = sorted(values)
            if known:
                values[k] = values[min(known, key=lambda x: min((x-k) % period, (k-x) % period))]
            else:
                values[k] = 0

    return [[values[(c + r) % period] for c in range(w)] for r in range(h)]
