def transform(grid):
    h, w = len(grid), len(grid[0])
    # Colored diagonals specify entries of a repeating diagonal pattern.
    # Recover its period from the row/column shifts of the marked diagonals.
    marks = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                marks[c - r] = grid[r][c]

    # The pattern period is the smallest shift that preserves all observed
    # diagonal markings.
    period = h
    for p in range(1, h + 1):
        if all(d + p not in marks or marks[d + p] == color
               for d, color in marks.items()):
            period = p
            break

    # Extend the diagonal markings periodically; unmarked residues are
    # interpolated by the nearest marked diagonal.
    residues = {d % period: color for d, color in marks.items()}
    def value(d):
        k = d % period
        if k in residues:
            return residues[k]
        nearest = min(residues, key=lambda x: min((x-k) % period, (k-x) % period))
        return residues[nearest]

    return [[value(c-r) for c in range(w)] for r in range(h)]
